algorithms.pseudocode:
function FIB_RANK(m):
    require m >= 1
    if m == 1: return 1
    (a, b) <- (0, 1)            # (Fib(0), Fib(1)) mod m
    for k from 1 to m*m:
        (a, b) <- (b mod m, (a + b) mod m)   # state pair (Fib(k), Fib(k+1)) mod m
        if a == 0:
            return k            # least positive index with m | Fib(k)
    # unreachable: the finite-state orbit is purely periodic
